def titulo():
    return t("Heat and waves", "El calor y las ondas")


def anc(en, es):
    return en if C.L == "en" else es


def R(x):
    return f'<span class="raiz">{x}</span>'


def fmt(x):
    return format(D(x).normalize(), "f")


def svg_caminos():
    tr = {"Conducción": "Conduction", "Convección": "Convection", "Radiación": "Radiation", "Por contacto directo,": "By direct contact,", "a través del material.": "through the material.",
          "Cuchara en una olla": "Spoon in a pot", "Lo caliente sube, lo frío baja:": "Warm rises, cool sinks:", "se forma una corriente.": "a current forms.",
          "Agua hirviendo, aire de un cuarto": "Boiling water, air in a room", "En forma de ondas.": "As waves.", "No necesita ningún material.": "Needs no material at all.",
          "El calor del Sol": "The Sun’s heat", "Solo la radiación atraviesa el vacío: las otras dos necesitan materia": "Only radiation crosses empty space: the other two need matter"}
    return C.svg_orig("6-3_0", tr, "The three ways heat moves. First, conduction: heat travels by direct contact through a material, as in the metal handle of a spoon resting in a hot pot; it needs matter, with its particles touching. Second, convection: in a fluid, the warm part rises because it is less dense and the cool part sinks, forming a loop-shaped current; it happens in the water of a boiling pot and in the air of a heated room. Third, radiation: heat travels as electromagnetic waves and needs no material to carry it, which is why the Sun’s heat crosses empty space.")


def svg_onda():
    tr = {"reposo": "rest", "Cresta": "Crest", "Valle": "Trough", "Longitud de onda (λ)": "Wavelength (λ)", "Amplitud": "Amplitude", "(energía que transporta)": "(energy it carries)",
          "Frecuencia: cuántas ondas completas pasan por un punto en un segundo · se mide en hercios (Hz)": "Frequency: how many complete waves pass a point in one second · measured in hertz (Hz)"}
    return C.svg_orig("6-3_1", tr, "Labeled diagram of a wave. The horizontal center line is the rest position. The highest points of the curve are called crests and the lowest, troughs. The wavelength is the distance between two crests in a row, or two troughs in a row, and is written with the Greek letter lambda. The amplitude is the vertical distance from the rest position to a crest, and it shows the energy the wave carries. The frequency is the number of complete waves that pass a point in one second, measured in hertz.")


def svg_espectro():
    tr = {k: k for k in ("10³ m", "10⁻² m", "10⁻⁵ m", "10⁻⁷ m", "10⁻⁸ m", "10⁻¹⁰ m", "10⁻¹² m")}
    tr.update({"Radio": "Radio", "Microondas": "Microwaves", "Infrarrojo": "Infrared", "Visible": "Visible", "Ultravioleta": "Ultraviolet", "Rayos X": "X-rays", "Rayos gamma": "Gamma rays",
               "Longitud de onda aproximada (orden de magnitud)": "Approximate wavelength (order of magnitude)", "La longitud de onda disminuye →": "Wavelength gets shorter →",
               "→ la frecuencia y la energía aumentan": "→ frequency and energy go up",
               "Izquierda: ondas largas, poca energía. Atraviesan obstáculos y se usan para comunicar.": "Left: long waves, little energy. They pass through obstacles and are used to communicate.",
               "Derecha: ondas cortísimas, mucha energía. Penetran en la materia y pueden dañar las células.": "Right: very short waves, a lot of energy. They go into matter and can damage cells."})
    return C.svg_orig("6-3_2", tr, "Diagram of the electromagnetic spectrum ordered from left to right. At the far left are radio waves, with very long wavelengths, on the order of meters or kilometers, low frequency, and low energy. Then come microwaves, infrared, the narrow band of visible light, ultraviolet, X-rays and, at the far right, gamma rays, with tiny wavelengths, high frequency, and high energy. The general rule is that as wavelength gets shorter, frequency and energy go up.")


