    def item(tit, piezas):
        return {"titulo": tit, "intro": t("Sort each situation by the way heat mainly moves.", "Clasifique cada situación según el mecanismo principal."), "grupos": G, "etiqueta": t("Way:", "Mecanismo:"),
                "piezas": [{"t": a, "v": v, "pista": PI[v]} for a, v in piezas], "extra": t("Contact → conduction; moving fluid → convection; waves, even through empty space → radiation.", "Contacto → conducción; fluido que circula → convección; ondas, incluso a través del vacío → radiación.")}
